data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
count = 0
for z in a:
    good = False
    for x in range(1, z + 1):
        for y in range(1, z + 1):
            if x != y and (x ^ y) == z and (x & y) == 0:
                good = True
    if good:
        count += 1
print(count)

