def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1, 2, 3, 4, 5, 6, 7]), fmt([8, 16, 1]), fmt([12, 10, 1024, 1023, 1023]), fmt([1]), fmt([3]), fmt([2, 2, 2])]
    for _ in range(30):
        n = rng.randint(1, 12)
        tests.append(fmt([rng.randint(1, 60) for _ in range(n)]))
    N = 10 ** 5
    tests.append(fmt([rng.randint(1, 10 ** 9) for _ in range(N)]))
    tests.append(fmt([1 << rng.randint(0, 29) for _ in range(N)]))
    tests.append(fmt([rng.choice([1 << rng.randint(0, 29), rng.randint(1, 10 ** 9)]) for _ in range(N)]))
    tests.append(fmt([10 ** 9] * N))
    return tests

